grammar:[GR("Ja/Nein-Fragen","أسئلة نعم/لا",`<p>Bei Ja/Nein-Fragen steht das Verb auf Position 1.</p><div class="exbox"><b>Kommst</b> du am Samstag? - Ja, gern.<br><b>Arbeiten</b> Sie am Montag? - Nein, ich habe frei.</div>`),GR("Bestimmte Artikel und haben/sein","أدوات التعريف وفعلا haben/sein",`<div class="gt-wrap"><table class="gt"><tr><th>Artikel</th><th>Beispiel</th></tr><tr><td>der</td><td>der Beruf, der Montag</td></tr><tr><td>das</td><td>das Hobby, das Formular</td></tr><tr><td>die</td><td>die Lehrerin, die Woche</td></tr></table></div><p><b>haben</b>: ich habe, du hast, er hat. <b>sein</b>: ich bin, du bist, er ist.</p>`),GR("Zahlen ab 20","الأرقام من 20 وطريقة تكوينها",`<p>Ab 21 sagt man zuerst die <b>Einer</b>, dann <b>und</b>, dann die <b>Zehner</b>: <b>einundzwanzig</b> (1+20).</p><div class="gt-wrap"><table class="gt"><tr><th>Zahl</th><th>Deutsch</th><th>نطق تقريبي</th></tr><tr><td>20</td><td>zwanzig</td><td>تسفانتسيش</td></tr><tr><td>21</td><td>einundzwanzig</td><td>آين-اوُنت-تسفانتسيش</td></tr><tr><td>22</td><td>zweiundzwanzig</td><td>تسفاي-اوُنت-تسفانتسيش</td></tr><tr><td>30</td><td>dreißig</td><td>درايسيش</td></tr><tr><td>40</td><td>vierzig</td><td>فيرتسيش</td></tr><tr><td>50</td><td>fünfzig</td><td>فُنفتسيش</td></tr><tr><td>60</td><td>sechzig</td><td>زِشتسيش</td></tr><tr><td>70</td><td>siebzig</td><td>زيبتسيش</td></tr><tr><td>80</td><td>achtzig</td><td>أختتسيش</td></tr><tr><td>90</td><td>neunzig</td><td>نوينتسيش</td></tr><tr><td>100</td><td>(ein)hundert</td><td>هوُندِرت</td></tr></table></div>`),GR("Aussprache: Satzmelodie","النطق: نغمة الجملة (صعود/هبوط)",`<p>Die Stimme zeigt die Satzart:</p><div class="exbox">Aussage ↘: Ich komme aus Ägypten.<br>W-Frage ↘: Woher kommst du?<br>Ja/Nein-Frage ↗: Kommst du aus Kairo?</div><p>Bei Ja/Nein-Fragen geht die Stimme am Ende nach <b>oben</b>.</p>`)],
