readings:[READ("Stadtplan","Ein Tag in Hamburg",
 "Sara ist zum ersten Mal in Hamburg. Sie möchte zum Hafen und fragt eine Frau nach dem Weg. Die Frau sagt: Gehen Sie geradeaus bis zur U-Bahn. Fahren Sie zwei Stationen. Dann gehen Sie rechts. Der Hafen ist nicht weit. Sara macht Fotos und besucht am Nachmittag ein Museum.",
 "سارة في هامبورغ لأول مرة. تريد الذهاب إلى الميناء وتسأل سيدة عن الطريق. تركب المترو محطتين ثم تمشي يمين. بعد ذلك تزور متحفا.",
 [["zum ersten Mal","لأول مرة"],["der Hafen","الميناء"],["besuchen","يزور"]],
 [["Wohin möchte Sara?","Zum Hafen."],["Wie viele Stationen fährt sie?","Zwei Stationen."],["Was besucht sie am Nachmittag?","Ein Museum."]])],
grammar:[GR("Unbestimmter Artikel und Negation","أداة النكرة والنفي",`<div class="gt-wrap"><table class="gt"><tr><th>positiv</th><th>negativ</th></tr><tr><td>Das ist ein Park.</td><td>Das ist kein Park.</td></tr><tr><td>Hier ist eine Kirche.</td><td>Hier ist keine Kirche.</td></tr></table></div><p><b>nicht</b> negiert Verben oder Adjektive: Der Bahnhof ist <b>nicht</b> weit.</p>`),GR("Imperativ mit Sie","الأمر الرسمي مع Sie",`<p>Für höfliche Wegbeschreibungen benutzt man den Imperativ mit <b>Sie</b>.</p><div class="exbox">Gehen Sie geradeaus. Nehmen Sie den Bus. Biegen Sie rechts ab.</div>`),GR("Aussprache: lange und kurze Vokale","النطق: حروف العلة الطويلة والقصيرة",`<p>Ein Vokal ist meist <b>lang</b> vor <b>h</b> oder vor nur einem Konsonanten, und <b>kurz</b> vor zwei Konsonanten.</p><div class="gt-wrap"><table class="gt"><tr><th>lang (طويلة)</th><th>kurz (قصيرة)</th></tr><tr><td>wohnen, Bahn</td><td>kommen, Mann</td></tr><tr><td>Stuhl, gut</td><td>muss, Bus</td></tr><tr><td>Weg, Reise</td><td>Bett, Stadt</td></tr></table></div><p>Hör genau: <b>ah/oh/uh</b> klingen lang und ruhig.</p>`)],
